declare const isoTimestampBrand: unique symbol;

/** UTC instant stored as an ISO-8601 string. Lexicographic order matches time order. */
export type IsoTimestamp = string & { readonly [isoTimestampBrand]: "IsoTimestamp" };

export function toIsoTimestamp(date: Date): IsoTimestamp {
  return date.toISOString() as IsoTimestamp;
}

declare const idBrand: unique symbol;

type Brand<T, Name extends string> = T & { readonly [idBrand]: Name };

export type UserId = Brand<string, "UserId">;
export type OrgId = Brand<string, "OrgId">;
export type SessionId = Brand<string, "SessionId">;

import { randomBytes } from "node:crypto";

const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

/** Opaque 26-character id. The anonymous-org sentinel uses the same width. */
export function newId(size = 26): string {
  const bytes = randomBytes(size);
  let id = "";
  for (let index = 0; index < size; index += 1) {
    id += ALPHABET[bytes[index]! % ALPHABET.length];
  }
  return id;
}

/** Addresses compare and bucket without regard to letter case or surrounding space. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

const SCRYPT_N = 2048;
const SCRYPT_R = 8;
const SCRYPT_P = 1;
const KEY_LENGTH = 32;

export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, KEY_LENGTH, {
    N: SCRYPT_N,
    r: SCRYPT_R,
    p: SCRYPT_P,
  }).toString("hex");
  return `scrypt$${SCRYPT_N}$${SCRYPT_R}$${SCRYPT_P}$${salt}$${hash}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [scheme, nRaw, rRaw, pRaw, salt, hash] = stored.split("$");
  if (scheme !== "scrypt" || !nRaw || !rRaw || !pRaw || !salt || !hash) return false;
  const n = Number(nRaw);
  const r = Number(rRaw);
  const p = Number(pRaw);
  if (!Number.isFinite(n) || !Number.isFinite(r) || !Number.isFinite(p)) return false;
  const actual = scryptSync(password, salt, KEY_LENGTH, { N: n, r, p });
  const expected = Buffer.from(hash, "hex");
  if (expected.length !== actual.length) return false;
  return timingSafeEqual(actual, expected);
}

import { integer, sqliteTable, text } from "drizzle-orm/sqlite-core";

export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  name: text("name").notNull(),
  createdAt: text("created_at").notNull(),
});

export const organizations = sqliteTable("organizations", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  createdAt: text("created_at").notNull(),
});

export const memberships = sqliteTable("memberships", {
  id: text("id").primaryKey(),
  organizationId: text("organization_id").notNull(),
  userId: text("user_id").notNull(),
  role: text("role").notNull(),
  createdAt: text("created_at").notNull(),
});

export const sessions = sqliteTable("sessions", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  createdAt: text("created_at").notNull(),
  expiresAt: text("expires_at").notNull(),
});

export const passwordResetTokens = sqliteTable("password_reset_tokens", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  tokenHash: text("token_hash").notNull().unique(),
  expiresAt: text("expires_at").notNull(),
  usedAt: text("used_at"),
  createdAt: text("created_at").notNull(),
});

/** Separate buckets so sign-in failures and reset requests never share a counter. */
export const authRateLimits = sqliteTable("auth_rate_limits", {
  bucketKey: text("bucket_key").primaryKey(),
  count: integer("count").notNull(),
  windowStartedAt: text("window_started_at").notNull(),
});

import Database from "better-sqlite3";
import { drizzle, type BetterSQLite3Database } from "drizzle-orm/better-sqlite3";

import * as schema from "@/server/db/schema";

export {
  authRateLimits,
  memberships,
  organizations,
  passwordResetTokens,
  sessions,
  users,
} from "@/server/db/schema";

const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS users (
  id text PRIMARY KEY NOT NULL,
  email text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  name text NOT NULL,
  created_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS organizations (
  id text PRIMARY KEY NOT NULL,
  name text NOT NULL,
  slug text NOT NULL UNIQUE,
  created_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS memberships (
  id text PRIMARY KEY NOT NULL,
  organization_id text NOT NULL,
  user_id text NOT NULL,
  role text NOT NULL,
  created_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  id text PRIMARY KEY NOT NULL,
  user_id text NOT NULL,
  created_at text NOT NULL,
  expires_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id text PRIMARY KEY NOT NULL,
  user_id text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  expires_at text NOT NULL,
  used_at text,
  created_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS auth_rate_limits (
  bucket_key text PRIMARY KEY NOT NULL,
  count integer NOT NULL,
  window_started_at text NOT NULL
);
`;

let sqlite: Database.Database | null = null;
let orm: BetterSQLite3Database<typeof schema> | null = null;
let openedUrl: string | null = null;

function databaseUrl(): string {
  return process.env.DATABASE_URL ?? ":memory:";
}

function open(url: string): void {
  if (sqlite) sqlite.close();
  sqlite = new Database(url);
  sqlite.exec(SCHEMA_SQL);
  orm = drizzle(sqlite, { schema });
  openedUrl = url;
}

export function getDb(): BetterSQLite3Database<typeof schema> {
  const url = databaseUrl();
  if (!orm || !sqlite || openedUrl !== url) open(url);
  return orm!;
}

/** Drops auth rows so a caller can reuse one process-wide connection. */
export function resetDatabase(): void {
  getDb();
  sqlite!.exec(`
    DELETE FROM auth_rate_limits;
    DELETE FROM password_reset_tokens;
    DELETE FROM sessions;
    DELETE FROM memberships;
    DELETE FROM organizations;
    DELETE FROM users;
  `);
}

export type PasswordResetMessage = {
  to: string;
  token: string;
  url: string;
};

const outbox: PasswordResetMessage[] = [];

/** Records the reset link. Callers observe the outbox instead of a mailbox. */
export async function sendPasswordResetEmail(message: PasswordResetMessage): Promise<void> {
  outbox.push(message);
}

export function sentPasswordResetEmails(): readonly PasswordResetMessage[] {
  return outbox;
}

export function clearPasswordResetEmails(): void {
  outbox.length = 0;
}

