import { and, eq, gt, lt } from "drizzle-orm";

import { newId } from "@/lib/id";
import { getDb, sessions } from "@/server/db";
import { toIsoTimestamp, type IsoTimestamp } from "@/types/common";

export type Session = {
  id: string;
  userId: string;
  createdAt: IsoTimestamp;
  expiresAt: IsoTimestamp;
};

function toSession(row: {
  id: string;
  userId: string;
  createdAt: string;
  expiresAt: string;
}): Session {
  return {
    id: row.id,
    userId: row.userId,
    createdAt: row.createdAt as IsoTimestamp,
    expiresAt: row.expiresAt as IsoTimestamp,
  };
}

export async function insertSession(input: {
  userId: string;
  expiresAt: IsoTimestamp;
  createdAt?: IsoTimestamp;
  id?: string;
}): Promise<Session> {
  const row: Session = {
    id: input.id ?? newId(),
    userId: input.userId,
    createdAt: input.createdAt ?? toIsoTimestamp(new Date()),
    expiresAt: input.expiresAt,
  };
  getDb().insert(sessions).values(row).run();
  return row;
}

/** Raw row, including one that is already past its expiry. */
export async function findSessionById(sessionId: string): Promise<Session | null> {
  const row = getDb().select().from(sessions).where(eq(sessions.id, sessionId)).get();
  return row ? toSession(row) : null;
}

/**
 * Session cookie check. A missing id and an id whose expiry has been reached
 * are both refused. `expiresAt` is the first instant the session is invalid.
 */
export async function findActiveSession(
  sessionId: string,
  now: IsoTimestamp = toIsoTimestamp(new Date()),
): Promise<Session | null> {
  const row = getDb()
    .select()
    .from(sessions)
    .where(and(eq(sessions.id, sessionId), gt(sessions.expiresAt, now)))
    .get();
  return row ? toSession(row) : null;
}

export async function deleteSession(sessionId: string): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/** Ends every session for one account. Other accounts are not touched. */
export async function deleteSessionsForUser(userId: string): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.userId, userId)).run();
}

/** Housekeeping sweep; returns how many rows the scheduler removed. */
export async function purgeExpiredSessions(now: IsoTimestamp): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/**
 * Password-reset tokens are single-use and belong to one account. The account
 * entry owns it, and `AuthService` cannot implement a real reset flow without
 * somewhere to keep the single-use token.
 */
import { and, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, passwordResetTokens } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type ResetToken = {
  id: string;
  userId: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  usedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
};

function toResetToken(row: {
  id: string;
  userId: string;
  tokenHash: string;
  expiresAt: string;
  usedAt: string | null;
  createdAt: string;
}): ResetToken {
  return {
    id: row.id,
    userId: row.userId,
    tokenHash: row.tokenHash,
    expiresAt: row.expiresAt as IsoTimestamp,
    usedAt: row.usedAt === null ? null : (row.usedAt as IsoTimestamp),
    createdAt: row.createdAt as IsoTimestamp,
  };
}

export async function insertResetToken(input: {
  userId: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
}): Promise<ResetToken> {
  const createdAt = toIsoTimestamp(new Date());
  const row = {
    id: newId(),
    userId: input.userId,
    tokenHash: input.tokenHash,
    expiresAt: input.expiresAt,
    usedAt: null as string | null,
    createdAt,
  };
  getDb().insert(passwordResetTokens).values(row).run();
  return toResetToken({ ...row, usedAt: null });
}

/** Returns the token only while it is unused and unexpired. */
export async function findLiveResetToken(tokenHash: string): Promise<ResetToken | null> {
  const row = getDb()
    .select()
    .from(passwordResetTokens)
    .where(
      and(
        eq(passwordResetTokens.tokenHash, tokenHash),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
      ),
    )
    .get();
  return row ? toResetToken(row) : null;
}

/**
 * Single-use consume. A second call, an expired token, or an unknown hash
 * changes nothing and returns null.
 */
export async function consumeResetToken(tokenHash: string): Promise<ResetToken | null> {
  const now = new Date().toISOString();
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: now })
    .where(
      and(
        eq(passwordResetTokens.tokenHash, tokenHash),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, now),
      ),
    )
    .returning()
    .all();
  const row = rows[0];
  return row ? toResetToken(row) : null;
}

/**
 * Retires every earlier unused link for this account. Links that belong to
 * someone else stay usable, and the caller inserts the replacement afterwards
 * so the new link is not retired along with the old ones.
 */
export async function retireUnusedResetTokens(
  userId: string,
  retiredAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(passwordResetTokens)
    .set({ usedAt: retiredAt })
    .where(and(eq(passwordResetTokens.userId, userId), isNull(passwordResetTokens.usedAt)))
    .run();
}

export {
  consumeResetToken,
  findLiveResetToken,
  insertResetToken,
  retireUnusedResetTokens,
  type ResetToken,
} from "@/server/repositories/_password-reset-repository";

import { eq } from "drizzle-orm";

import { normalizeEmail } from "@/lib/email";
import { newId } from "@/lib/id";
import { getDb, memberships, organizations, users } from "@/server/db";
import { toIsoTimestamp, type IsoTimestamp } from "@/types/common";

export type UserRecord = {
  id: string;
  email: string;
  passwordHash: string;
  name: string;
  createdAt: IsoTimestamp;
};

function toUser(row: {
  id: string;
  email: string;
  passwordHash: string;
  name: string;
  createdAt: string;
}): UserRecord {
  return {
    id: row.id,
    email: row.email,
    passwordHash: row.passwordHash,
    name: row.name,
    createdAt: row.createdAt as IsoTimestamp,
  };
}

export async function findUserByEmail(email: string): Promise<UserRecord | null> {
  const row = getDb()
    .select()
    .from(users)
    .where(eq(users.email, normalizeEmail(email)))
    .get();
  return row ? toUser(row) : null;
}

export async function findUserById(userId: string): Promise<UserRecord | null> {
  const row = getDb().select().from(users).where(eq(users.id, userId)).get();
  return row ? toUser(row) : null;
}

export async function insertUserWithWorkspace(input: {
  email: string;
  passwordHash: string;
  name: string;
}): Promise<{ userId: string; organizationId: string; email: string }> {
  const createdAt = toIsoTimestamp(new Date());
  const userId = newId();
  const organizationId = newId();
  const email = normalizeEmail(input.email);
  const slugBase =
    input.name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "") || "workspace";
  const slug = `${slugBase}-${organizationId.slice(0, 6).toLowerCase()}`;

  getDb().insert(users).values({
    id: userId,
    email,
    passwordHash: input.passwordHash,
    name: input.name,
    createdAt,
  }).run();
  getDb().insert(organizations).values({
    id: organizationId,
    name: `${input.name}'s workspace`,
    slug,
    createdAt,
  }).run();
  getDb().insert(memberships).values({
    id: newId(),
    organizationId,
    userId,
    role: "owner",
    createdAt,
  }).run();

  return { userId, organizationId, email };
}

export async function updateUserPassword(userId: string, passwordHash: string): Promise<void> {
  getDb().update(users).set({ passwordHash }).where(eq(users.id, userId)).run();
}

import { eq } from "drizzle-orm";

import { getDb, authRateLimits } from "@/server/db";

/**
 * Fixed window keyed by the caller. Sign-in and password-reset use different
 * keys, and each address has its own key, so one account cannot lock another
 * and a sign-in lock cannot block a reset.
 */
export async function isBucketLimited(
  bucketKey: string,
  now: Date,
  limit: number,
  windowMs: number,
): Promise<boolean> {
  const existing = getDb()
    .select()
    .from(authRateLimits)
    .where(eq(authRateLimits.bucketKey, bucketKey))
    .get();
  if (!existing) return false;
  if (now.getTime() - Date.parse(existing.windowStartedAt) >= windowMs) return false;
  return existing.count >= limit;
}

export async function recordBucketHit(
  bucketKey: string,
  now: Date,
  windowMs: number,
): Promise<void> {
  const db = getDb();
  const existing = db
    .select()
    .from(authRateLimits)
    .where(eq(authRateLimits.bucketKey, bucketKey))
    .get();
  const nowIso = now.toISOString();
  const windowOpen =
    existing !== undefined && now.getTime() - Date.parse(existing.windowStartedAt) < windowMs;

  if (!existing || !windowOpen) {
    db.insert(authRateLimits)
      .values({ bucketKey, count: 1, windowStartedAt: nowIso })
      .onConflictDoUpdate({
        target: authRateLimits.bucketKey,
        set: { count: 1, windowStartedAt: nowIso },
      })
      .run();
    return;
  }

  db.update(authRateLimits)
    .set({ count: existing.count + 1 })
    .where(eq(authRateLimits.bucketKey, bucketKey))
    .run();
}

import { createHash, randomBytes } from "node:crypto";

import { normalizeEmail } from "@/lib/email";
import { hashPassword, verifyPassword } from "@/lib/password";
import { isBucketLimited, recordBucketHit } from "@/server/repositories/auth-rate-limit-repository";
import {
  consumeResetToken,
  insertResetToken,
  retireUnusedResetTokens,
} from "@/server/repositories/_password-reset-repository";
import {
  deleteSession,
  deleteSessionsForUser,
  findActiveSession,
  insertSession,
  type Session,
} from "@/server/repositories/session-repository";
import {
  findUserByEmail,
  insertUserWithWorkspace,
  updateUserPassword,
} from "@/server/repositories/user-repository";
import { sendPasswordResetEmail } from "@/server/mailer";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/ids";

/**
 * Placeholder organization for code paths that need an org id before anyone
 * has signed in. It is not a workspace and it has no members.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Registration creates the user and their first workspace in one step — a
 * new account with nowhere to land is not a finished sign-up.
 */
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;
const REMEMBER_SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** Wrong passwords recorded against one address before sign-in is refused. */
const SIGN_IN_ATTEMPT_LIMIT = 5;
const SIGN_IN_WINDOW_MS = 15 * 60 * 1000;

/** Reset emails requested for one address before further requests are refused. */
const RESET_REQUEST_LIMIT = 5;
const RESET_REQUEST_WINDOW_MS = 15 * 60 * 1000;

export class AuthError extends Error {
  readonly code: "TOO_MANY_ATTEMPTS" | "INVALID_CREDENTIALS" | "RESET_TOKEN_INVALID" | "EMAIL_IN_USE";

  constructor(
    code: "TOO_MANY_ATTEMPTS" | "INVALID_CREDENTIALS" | "RESET_TOKEN_INVALID" | "EMAIL_IN_USE",
    message: string,
  ) {
    super(message);
    this.name = "AuthError";
    this.code = code;
  }
}

export type SignInInput = {
  email: string;
  password: string;
  rememberMe?: boolean;
};

export type RegisterInput = {
  email: string;
  password: string;
  name?: string;
};

export type RegisteredAccount = {
  userId: string;
  organizationId: string;
  email: string;
};

function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

function signInBucket(email: string): string {
  return `sign_in:${email}`;
}

function resetBucket(email: string): string {
  return `password_reset:${email}`;
}

export function anonymousOrganizationId(): OrgId {
  return ANONYMOUS_ORG;
}

export class AuthService {
  /**
   * Creates the person and their first workspace together. The stored address
   * is lower-cased so later sign-in and reset lookups match any letter case.
   */
  async register(input: RegisterInput): Promise<RegisteredAccount> {
    const email = normalizeEmail(input.email);
    const existing = await findUserByEmail(email);
    if (existing) {
      throw new AuthError("EMAIL_IN_USE", "an account with that email already exists");
    }
    const name = input.name?.trim() || email.split("@")[0] || "New member";
    return insertUserWithWorkspace({
      email,
      passwordHash: hashPassword(input.password),
      name,
    });
  }

  /**
   * A shared computer gets a day. Remember-me keeps the same session for 30
   * days. Failures are counted for this address only; once the window is
   * full, the right password is refused until the window recovers. Reset
   * traffic uses a different bucket and is not affected.
   */
  async signIn(input: SignInInput): Promise<Session> {
    const email = normalizeEmail(input.email);
    const now = new Date();
    if (await isBucketLimited(signInBucket(email), now, SIGN_IN_ATTEMPT_LIMIT, SIGN_IN_WINDOW_MS)) {
      throw new AuthError("TOO_MANY_ATTEMPTS", "too many attempts");
    }

    const user = await findUserByEmail(email);
    if (!user || !verifyPassword(input.password, user.passwordHash)) {
      await recordBucketHit(signInBucket(email), now, SIGN_IN_WINDOW_MS);
      throw new AuthError("INVALID_CREDENTIALS", "invalid email or password");
    }

    const ttl = input.rememberMe === true ? REMEMBER_SESSION_TTL_MS : SESSION_TTL_MS;
    return insertSession({
      userId: user.id,
      createdAt: toIsoTimestamp(now),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + ttl)),
    });
  }

  /**
   * Ends that session and only that one. An unknown or already-ended id
   * deletes nothing and does not touch anyone else's session.
   */
  async signOut(sessionId: string): Promise<void> {
    await deleteSession(sessionId);
  }

  /** Refuses a session that is missing or whose expiry has been reached. */
  async getSession(sessionId: string): Promise<Session | null> {
    return findActiveSession(sessionId);
  }

  /**
   * Always completes for an unknown address, and sends nothing in that case.
   * A new link retires every earlier unused link for this account only.
   * Requests are limited per address, separate from sign-in failures.
   */
  async requestPasswordReset(email: string): Promise<void> {
    const normalized = normalizeEmail(email);
    const now = new Date();
    if (
      await isBucketLimited(
        resetBucket(normalized),
        now,
        RESET_REQUEST_LIMIT,
        RESET_REQUEST_WINDOW_MS,
      )
    ) {
      throw new AuthError("TOO_MANY_ATTEMPTS", "too many attempts");
    }
    await recordBucketHit(resetBucket(normalized), now, RESET_REQUEST_WINDOW_MS);

    const user = await findUserByEmail(normalized);
    if (!user) return;

    await retireUnusedResetTokens(user.id, toIsoTimestamp(now));
    const token = randomBytes(32).toString("base64url");
    await insertResetToken({
      userId: user.id,
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + RESET_TTL_MS)),
    });
    await sendPasswordResetEmail({
      to: user.email,
      token,
      url: `/reset-password/${token}`,
    });
  }

  /**
   * The link works once, and only for 60 minutes after it was sent. Success
   * replaces the password and ends every session of this account. Other
   * accounts stay signed in, and a sign-in throttle does not block this.
   */
  async resetPassword(token: string, newPassword: string): Promise<void> {
    const consumed = await consumeResetToken(hashToken(token));
    if (!consumed) {
      throw new AuthError("RESET_TOKEN_INVALID", "no longer valid");
    }
    await updateUserPassword(consumed.userId, hashPassword(newPassword));
    await deleteSessionsForUser(consumed.userId);
  }
}

