} from "@/server/repositories/user-repository";
import { sendPasswordResetEmail } from "@/server/mailer";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/ids";

/**
 * Placeholder organization for code paths that need an org id before anyone
 * has signed in. It is not a workspace and it has no members.
