const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Registration creates the user and their first workspace in one step — a
 * new account with nowhere to land is not a finished sign-up.
 */
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;
const REMEMBER_SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** Wrong passwords recorded against one address before sign-in is refused. */
const SIGN_IN_ATTEMPT_LIMIT = 5;
const SIGN_IN_WINDOW_MS = 15 * 60 * 1000;

/** Reset emails requested for one address before further requests are refused. */
const RESET_REQUEST_LIMIT = 5;
const RESET_REQUEST_WINDOW_MS = 15 * 60 * 1000;

export class AuthError extends Error {
  readonly code: "TOO_MANY_ATTEMPTS" | "INVALID_CREDENTIALS" | "RESET_TOKEN_INVALID" | "EMAIL_IN_USE";

  constructor(
    code: "TOO_MANY_ATTEMPTS" | "INVALID_CREDENTIALS" | "RESET_TOKEN_INVALID" | "EMAIL_IN_USE",
    message: string,
  ) {
    super(message);
    this.name = "AuthError";
    this.code = code;
  }
}

export type SignInInput = {
  email: string;
  password: string;
  rememberMe?: boolean;
};

export type RegisterInput = {
  email: string;
  password: string;
  name?: string;
};

export type RegisteredAccount = {
  userId: string;
  organizationId: string;
  email: string;
};

function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

function signInBucket(email: string): string {
  return `sign_in:${email}`;
}

function resetBucket(email: string): string {
  return `password_reset:${email}`;
}

export function anonymousOrganizationId(): OrgId {
  return ANONYMOUS_ORG;
}

export class AuthService {
  /**
   * Creates the person and their first workspace together. The stored address
   * is lower-cased so later sign-in and reset lookups match any letter case.
   */
  async register(input: RegisterInput): Promise<RegisteredAccount> {
    const email = normalizeEmail(input.email);
    const existing = await findUserByEmail(email);
    if (existing) {
      throw new AuthError("EMAIL_IN_USE", "an account with that email already exists");
    }
    const name = input.name?.trim() || email.split("@")[0] || "New member";
    return insertUserWithWorkspace({
      email,
      passwordHash: hashPassword(input.password),
      name,
    });
  }

  /**
   * A shared computer gets a day. Remember-me keeps the same session for 30
   * days. Failures are counted for this address only; once the window is
   * full, the right password is refused until the window recovers. Reset
   * traffic uses a different bucket and is not affected.
   */
  async signIn(input: SignInInput): Promise<Session> {
    const email = normalizeEmail(input.email);
    const now = new Date();
    if (await isBucketLimited(signInBucket(email), now, SIGN_IN_ATTEMPT_LIMIT, SIGN_IN_WINDOW_MS)) {
      throw new AuthError("TOO_MANY_ATTEMPTS", "too many attempts");
    }

    const user = await findUserByEmail(email);
    if (!user || !verifyPassword(input.password, user.passwordHash)) {
      await recordBucketHit(signInBucket(email), now, SIGN_IN_WINDOW_MS);
      throw new AuthError("INVALID_CREDENTIALS", "invalid email or password");
    }

    const ttl = input.rememberMe === true ? REMEMBER_SESSION_TTL_MS : SESSION_TTL_MS;
    return insertSession({
      userId: user.id,
      createdAt: toIsoTimestamp(now),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + ttl)),
    });
  }

  /**
   * Ends that session and only that one. An unknown or already-ended id
   * deletes nothing and does not touch anyone else's session.
   */
  async signOut(sessionId: string): Promise<void> {
    await deleteSession(sessionId);
  }

  /** Refuses a session that is missing or whose expiry has been reached. */
  async getSession(sessionId: string): Promise<Session | null> {
    return findActiveSession(sessionId);
  }

  /**
   * Always completes for an unknown address, and sends nothing in that case.
   * A new link retires every earlier unused link for this account only.
   * Requests are limited per address, separate from sign-in failures.
   */
  async requestPasswordReset(email: string): Promise<void> {
    const normalized = normalizeEmail(email);
    const now = new Date();
    if (
      await isBucketLimited(
        resetBucket(normalized),
        now,
        RESET_REQUEST_LIMIT,
        RESET_REQUEST_WINDOW_MS,
      )
    ) {
      throw new AuthError("TOO_MANY_ATTEMPTS", "too many attempts");
    }
    await recordBucketHit(resetBucket(normalized), now, RESET_REQUEST_WINDOW_MS);

    const user = await findUserByEmail(normalized);
    if (!user) return;

    await retireUnusedResetTokens(user.id, toIsoTimestamp(now));
    const token = randomBytes(32).toString("base64url");
    await insertResetToken({
      userId: user.id,
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + RESET_TTL_MS)),
    });
    await sendPasswordResetEmail({
      to: user.email,
      token,
      url: `/reset-password/${token}`,
    });
  }

  /**
   * The link works once, and only for 60 minutes after it was sent. Success
   * replaces the password and ends every session of this account. Other
   * accounts stay signed in, and a sign-in throttle does not block this.
   */
  async resetPassword(token: string, newPassword: string): Promise<void> {
    const consumed = await consumeResetToken(hashToken(token));
    if (!consumed) {
      throw new AuthError("RESET_TOKEN_INVALID", "no longer valid");
    }
    await updateUserPassword(consumed.userId, hashPassword(newPassword));
    await deleteSessionsForUser(consumed.userId);
  }
}

